// SRTM elevation sampled from https://s3.amazonaws.com/elevation-tiles-prod/skadi/N24/N24E118.hgt.gz
const kinmenElevation=(()=>{
  const bytes=atob('');
  const result=new Int16Array(218*174);
  for(let i=0;i<result.length;i++) result[i]=bytes.charCodeAt(i*2)|(bytes.charCodeAt(i*2+1)<<8);
  return {west:118.03,north:24.62,step:0.002,columns:218,rows:174,heights:result};
})();
